alter table public.daily_checkins add column if not exists entry_details jsonb;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('checkin-photos','checkin-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "checkin_photos_read" on storage.objects for select to authenticated using (bucket_id='checkin-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "checkin_photos_upload" on storage.objects for insert to authenticated with check (bucket_id='checkin-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "checkin_photos_delete" on storage.objects for delete to authenticated using (bucket_id='checkin-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);